    "Docker تصویری را که کانتینر پیش‌تر روی آن اجرا می‌شد، حالا بدون برچسب نگه می‌دارد و Unraid آن را به‌عنوان تصویر یتیم فهرست می‌کند. این باقی‌ماندهٔ طبیعی یک به‌روزرسانی موفق است، نه نشانهٔ شکست، و درست همان چیزی است که بازگشت سریع به تصویر پیشین لازم دارد. اگر نمی‌خواهی نگه‌داشته شود، کلید «حذف ایمیج قدیمی پس از به‌روزرسانی» در تنظیمات، زمان‌بندی، به‌روزرسانی‌ها پس از پشتیبان‌گیری تصویر جایگزین‌شده را بلافاصله پس از به‌روزرسانی پاک می‌کند.",
