  "offsite.prune.info": "این گام فقط گزارش می‌دهد چه اتفاقی می‌افتد و چیزی را تنظیم نمی‌کند. اینکه این نسخه پاک‌سازی شود یا نه، با فقط-افزودنی در گام ۴ و مقادیر نگه‌داری در تنظیمات، مقصدها تعیین می‌شود. اگر باز هم می‌خواهی نسخه فقط-افزودنی را پاک‌سازی کنی، دستور restic forget --prune را روی خود مقصد اجرا کن، یا با زمان‌بندی جداگانه خودش یا با بالا آوردن کوتاه‌مدت یک سرور REST دوم بدون فقط-افزودنی، پاک‌سازی از طریق آن و سپس خاموش کردن دوباره‌اش.",
  "offsite.prune.stateFarSide": "از اینجا هیچ چیز این نسخه را پاک‌سازی نمی‌کند. فقط-افزودنی روشن است، پس BombVault تنها به آن می‌افزاید و پاک‌سازی کار خود مقصد است.",
  "offsite.prune.statePolicy": "BombVault این نسخه را پس از هر تکثیر، بر پایه سیاست نگه‌داری خارج از محل پاک‌سازی می‌کند.",
