  "excludes.advisoryImmichDb": "Immich آلبوم‌ها، چهره‌ها و تاریخ هر عکس را در یک پایگاه داده PostgreSQL نگه می‌دارد که در کانتینری جداگانه و مستقل اجرا می‌شود، پس این پشتیبان آن را در بر ندارد. بازیابی از اینجا عکس‌ها را برمی‌گرداند، اما بدون هیچ‌کدام از این‌ها. BombVault از کانتینر آن پایگاه داده هنگام پشتیبان‌گیری از آن، به‌طور خودکار دامپ می‌گیرد؛ پس بررسی کن که در زمان‌بندی‌ات باشد.",
  "excludes.advisoryNextcloudDb": "Nextcloud حساب‌ها، اشتراک‌ها و برچسب‌های خود را در پایگاه داده‌ای نگه می‌دارد که معمولاً در کانتینری جداگانه اجرا می‌شود، پس این پشتیبان آن را در بر ندارد. فایل‌ها برمی‌گردند، اشتراک‌گذاری نه. BombVault از کانتینر آن پایگاه داده هنگام پشتیبان‌گیری از آن، به‌طور خودکار دامپ می‌گیرد؛ پس بررسی کن که در زمان‌بندی‌ات باشد.",
