  "rcloneRemote.heading": "افزودن مقصد SMB یا WebDAV",
  "rcloneRemote.hint": "به یک اشتراک Windows یا Samba، یا یک سرور WebDAV مانند Nextcloud دسترسی پیدا می‌کند، بدون اینکه آن را روی میزبان متصل کند. restic نگه‌داشتن مخزن روی اشتراک CIFS متصل‌شده را توصیه نمی‌کند، و این روش اتصال را به‌کلی کنار می‌گذارد. رمز عبور به rclone سپرده می‌شود تا در قالب خودش ذخیره کند و هرگز به‌صورت متن آشکار نگه‌داری نمی‌شود. NFS اینجا ارائه نمی‌شود، چون نه restic و نه rclone از آن پشتیبانی نمی‌کنند: برای NFS، اشتراک را در Unraid متصل کن و یک مسیر پشتیبان‌گیری به آن اشاره بده.",
