  "dbdump.import": "درون‌ریزی به یک پایگاه دادهٔ تازه",
  "dbdump.importConfirm": "این برون‌ریز {engine} {version} در {container} درون‌ریزی شود؟ BombVault کانتینر را متوقف می‌کند، پوشهٔ دادهٔ آن را کنار می‌گذارد (نگه داشته می‌شود، چیزی حذف نمی‌شود)، کانتینر را با پوشهٔ دادهٔ خالی راه می‌اندازد و برون‌ریز را درون‌ریزی می‌کند. برنامه‌هایی که از این پایگاه داده استفاده می‌کنند وضعیت آن را در زمان برون‌ریز می‌بینند.",
  "dbdump.importConfirmNoVersion": "این برون‌ریز {engine} در {container} درون‌ریزی شود؟ BombVault کانتینر را متوقف می‌کند، پوشهٔ دادهٔ آن را کنار می‌گذارد (نگه داشته می‌شود، چیزی حذف نمی‌شود)، کانتینر را با پوشهٔ دادهٔ خالی راه می‌اندازد و برون‌ریز را درون‌ریزی می‌کند. برنامه‌هایی که از این پایگاه داده استفاده می‌کنند وضعیت آن را در زمان برون‌ریز می‌بینند.",
  "dbdump.importNoVersion": "این برون‌ریز نسخهٔ پایگاه دادهٔ خود را ثبت نمی‌کند. اگر سرور نتواند آن را بخواند، درون‌ریزی شکست می‌خورد.",
  "dbdump.importStops": "one=BombVault هنگام درون‌ریزی {apps} را هم متوقف می‌کند و پس از آن دوباره راه‌اندازی‌اش می‌کند. اگر درون‌ریزی پس از آغاز شکست بخورد، داده‌های قبلی کنار گذاشته می‌مانند و برنامه متوقف.|other=BombVault هنگام درون‌ریزی این برنامه‌ها را هم متوقف می‌کند: {apps}. پس از آن دوباره راه‌اندازی‌شان می‌کند. اگر درون‌ریزی پس از آغاز شکست بخورد، داده‌های قبلی کنار گذاشته می‌مانند و برنامه‌ها متوقف.",
