  "dbdump.importRefused.versionSameMajor": "سرور با نسخهٔ {server} کار می‌کند و برون‌ریز از {dump} است. MySQL و MariaDB برون‌ریز را فقط در همان نسخهٔ اصلی که از آن آمده درون‌ریزی می‌کنند، پس برای این درون‌ریزی از ایمیجی با نسخهٔ {dump} استفاده کن.",
