  "receiver.server.formIntro": "BombVault یک کانتینر rest-server در حالت append-only می‌سازد، آن را راه می‌اندازد و بررسی می‌کند که حذف را رد می‌کند. هر نمونهٔ گروه تو هنگام انتخاب سرور ورود مخصوص خودش را می‌گیرد.",
  "receiver.server.folder": "پوشه برای مخازن",
  "receiver.server.folderTip": "پشتیبان‌هایی که شریک‌هایت می‌فرستند اینجا، کنار فایل ورودهای سرور، ذخیره می‌شوند. یک اشتراک با فضای کافی انتخاب کن.",
  "receiver.server.port": "درگاه",
  "receiver.server.portTip": "درگاهی روی این دستگاه که سرور به آن گوش می‌دهد. اگر کانتینر دیگری از آن استفاده نمی‌کند، 8000 را نگه دار.",
  "receiver.server.host": "نشانی برای شریک‌ها (اختیاری)",
  "receiver.server.hostTip": "خالی بگذار تا شریک‌هایت از نشانی‌ای استفاده کنند که با آن به این BombVault می‌رسند. وقتی BombVault نشانی IP مخصوص خودش دارد، مثلاً روی br0، آن را پر کن، چون سرور روی نشانی میزبان گوش می‌دهد.",
