  "mcp.pickHint": "BombVault هر کلید را فقط یک بار، هنگام ساختنش، نشان داد. اگر دیگر آن را نداری، یکی تازه بساز.",
  "mcp.pickShared": "مرحلهٔ ۳ با فراخوانی بعدی با این کلید سبز می‌شود، هر کلاینتی که آن را انجام دهد. برای اینکه مطمئن شوی همین کلاینت بوده، به هر کلاینت کلید جداگانه بده، همان کاری که کلید تازه می‌کند.",
  "mcp.stepConfig": "افزودن BombVault به {name}",
