  "oauth.reads": "می‌تواند وضعیت پشتیبان‌ها را بخواند: چه چیزی محافظت می‌شود، هر مورد آخرین بار کی پشتیبان‌گیری شده، اجراها چطور پیش رفته‌اند و گزارش‌هایشان چه می‌گویند. بازیابی، حذف و تنظیمات در همین رابط وب می‌مانند.",
  "oauth.unverified": "BombVault این کلاینت را نمی‌شناسد و نام بالا را خودش انتخاب کرده است. فقط وقتی اجازه بده که همین حالا خودت این ورود را شروع کرده باشی.",
  "oauth.startedHere": "فقط وقتی اجازه بده که همین حالا خودت این ورود را شروع کرده باشی. پیوندی که کس دیگری برایت فرستاده ممکن است حساب {name} او را به BombVault تو وصل کند.",
  "oauth.loopback": "این کلاینت به برنامه‌ای روی رایانهٔ خودت برمی‌گردد و هر برنامه‌ای آنجا می‌تواند خود را جای آن جا بزند. فقط وقتی اجازه بده که همین حالا خودت این ورود را شروع کرده باشی.",
  "oauth.allowStartHint": "با روشن بودن این گزینه، کلاینت می‌تواند پشتیبان‌گیری هم شروع کند و آن‌هایی را که خودش شروع کرده لغو کند، با همان محدودیت‌های یک کلید. پشتیبان‌گیری تا پایانش کانتینرهای در حال اجرا را متوقف می‌کند. بعدًا می‌توانی این را روی کاشی آن در تنظیمات، یکپارچه‌سازی‌ها، سرور MCP تغییر دهی.",
