  "oauth.errorBadRedirect": "این درخواست نشانی بازگشتی را نام می‌برد که کلاینت هرگز ثبت نکرده است، پس BombVault تو را آنجا نمی‌فرستد.",
  "oauth.errorInvalid": "کلاینت چیزی خواست که BombVault پشتیبانی نمی‌کند، پس ورود همین‌جا متوقف می‌شود.",
