  "mcp.oauthToggle": "ورود با OAuth",
  "mcp.oauthHint": "برای ChatGPT، Claude در claude.ai و سرویس‌های دیگری که کلید نمی‌پذیرند. تو را به صفحه‌ای از BombVault می‌فرستند که در آن با رمز ورودت وارد می‌شوی و به آن‌ها اجازه می‌دهی. آن‌ها BombVault را از سرورهای خودشان فراخوانی می‌کنند، پس BombVault باید در نشانی عمومی زیر از اینترنت در دسترس باشد، با گواهی‌ای که مرورگرها به آن اعتماد دارند. خاموش کردنش همهٔ کلاینت‌ها را خارج می‌کند.",
