  "mcp.oauthAddressHint": "نشانی https که BombVault در آن از اینترنت در دسترس است، مثلًا از طریق یک پراکسی معکوس، بدون مسیر، مانند https://backup.example.com. هر توکن به آن گره خورده است، پس پس از تغییر، هر کلاینت باید دوباره وارد شود.",
