  "mcp.stepOAuth": "ورود را روشن کن",
  "mcp.setupChatGPT": "در ChatGPT تنظیمات، برنامه‌ها و رابط‌ها را باز کن و در تنظیمات پیشرفته حالت توسعه‌دهنده را روشن کن. سپس ایجاد را بزن، برای رابط نامی بگذار، نشانی رابط را به‌عنوان نشانی سرور MCP بچسبان، OAuth را برای احراز هویت انتخاب کن، تأیید کن که به آن اعتماد داری و آن را بساز.",
  "mcp.setupClaudeAi": "در claude.ai تنظیمات، رابط‌ها را باز کن و افزودن رابط سفارشی را انتخاب کن. نامی برایش بگذار، نشانی رابط را بچسبان، شناسهٔ کلاینت و رمز OAuth را خالی بگذار و آن را اضافه کن. سپس اتصال را انتخاب کن.",
