  "anomaly.settings.title": "ناهنجاری‌ها",
  "anomaly.settings.hint": "هر پشتیبان یک مورد را با تاریخچهٔ خودش مقایسه می‌کند و آنچه را جور درنمی‌آید گزارش می‌دهد. پس از هر پشتیبان در پس‌زمینه اجرا می‌شود و هیچ‌کدام را کند نمی‌کند. بیشتر بررسی‌ها پس از 10 پشتیبان از یک مورد شروع می‌شوند؛ خطاها، بازنویسی بیشتر داده‌ها و منبعی که تقریباً خالی است از همان ابتدا بررسی می‌شوند. فضای آزاد برای مخزن‌های محلی و مخزن‌های rclone که آن را گزارش می‌دهند پایش می‌شود؛ در اشتراک کاربری Unraid این فضای آزاد کل آرایه است.",
