  "anomaly.settings.notifyMin": "ارسال اعلان برای",
  "anomaly.settings.notifyHint": "از کانال‌هایی که در اعلان‌ها تنظیم شده‌اند استفاده می‌کند. هر مورد می‌تواند آن را در ناهنجاری‌ها، پایش تغییر دهد. خطاهای تکراری پشتیبان و خروجی پایگاه داده و بررسی‌های بازیابی زمان‌بندی‌شدهٔ ناموفق از قبل پیام خودشان را می‌فرستند، پس بار دوم فرستاده نمی‌شوند.",
