  "anomaly.settings.openNotifications": "باز کردن تنظیمات اعلان",
  "anomaly.settings.holdToggle": "نگه داشتن پشتیبان‌های قدیمی وقتی منبعی به‌شدت کوچک یا بازنویسی می‌شود",
  "anomaly.settings.holdHint": "سه یافته حذف پشتیبان‌های قدیمی را متوقف می‌کنند: منبعی که ناگهان تقریباً خالی است، منبعی که بسیار کوچک‌تر شده، و پشتیبانی که بیشتر داده‌ها را دوباره ذخیره کرده است، همان چیزی که باج‌افزار به نظر می‌رسد. در غیر این صورت نگهداری، پشتیبان‌های قدیمی سالم را یکی‌یکی پاک می‌کرد. تا وقتی چنین ناهنجاری‌ای باز است، پشتیبان‌های قدیمی فقط همان مورد (یا همان خروجی پایگاه داده یا مجموعه‌دادهٔ ZFS) نگه داشته می‌شوند؛ بقیه طبق معمول پاک‌سازی می‌شوند. برای ادامه، ناهنجاری را تأیید کن یا آن را مورد انتظار علامت بزن.",
