  "whatsNew.windowTitleSince": "تازه‌ها از {version}",
  "whatsNew.overviewHead": "نقطه‌های سبز نشان می‌دهند چه چیزی تازه است. کلیک روی نقطه آن را پنهان می‌کند و همهٔ آن‌ها در تنظیمات، اطلاعات هستند.",
  "whatsNew.overviewCustomize": "بررسی اجمالی با پنج کارت شروع می‌شود. کارت‌های بیشتر زیر «شخصی‌سازی» منتظرند و هر کارت را می‌شود جابه‌جا کرد، اندازه‌اش را عوض کرد و پنهانش کرد.",
  "whatsNew.overviewDecline": "«پشتیبان‌گیری نکردن» موردی را که عمداً کنار می‌گذاری از این فهرست برمی‌دارد. بعد از آن دیگر محافظت‌نشده حساب نمی‌شود.",
  "whatsNew.overviewInstances": "در برنامه Android، بالای نمای کلی نام نمونه‌ای که در آن هستی دیده می‌شود. پیکان کنار نام تو را به نمای کلی برنامه برمی‌گرداند که همه نمونه‌هایت در آن فهرست شده‌اند.",
  "whatsNew.backupsTiles": "هرچه پشتیبان‌گیری می‌شود در یک فهرست است. کاشی‌ها یک نوع را انتخاب می‌کنند.",
  "whatsNew.backupsBar": "«فیلترها»، «مرتب‌سازی» و «جست‌وجو» سه دکمه بالای فهرست‌اند.",
  "whatsNew.backupsRow": "هر ردیف یک وضعیت نشان می‌دهد و بقیه در حبابِ کنار نام است. ردیف‌ها را مثل فایل‌ها انتخاب کن: Ctrl+کلیک، Shift+کلیک یا فشار طولانی.",
  "whatsNew.backupsActions": "کار اصلی هر صفحه پایین صفحه شناور است. «بیشتر» کارهای کم‌کاربرد را نگه می‌دارد.",
  "whatsNew.entryPage": "هر مورد صفحهٔ خودش را دارد، با سه تب: پشتیبان‌ها، تنظیمات و تأیید.",
  "whatsNew.entryDefaults": "یک مورد از زمان‌بندی و مقصد پیش‌فرض پیروی می‌کند تا اینجا مال خودش را بگیرد.",
  "whatsNew.restoreTiles": "«بازیابی» یک صفحه برای همه‌چیز است. یک حوزه را انتخاب کن یا دنبال یک مورد بگرد، بعد از خط زمانی‌اش یک پشتیبان بردار.",
  "whatsNew.restoreWhere": "یک پنجره می‌پرسد چه چیزی و کجا بازیابی شود. «کنار اصلی» یک نسخه برمی‌گرداند و اصلی را همان‌طور که هست می‌گذارد.",
  "whatsNew.restoreMany": "چند مورد را با Ctrl+کلیک، Shift+کلیک یا لمس طولانی انتخاب کن و با هم، یکی پس از دیگری، بازیابی کن.",
  "whatsNew.restoreEmergency": "دستیار اضطراری از اینجا شروع می‌شود. سروری را که از بین رفته یا دوباره راه‌اندازی شده، در چهار گام برمی‌گرداند.",
  "whatsNew.anomaliesTiles": "کاشی‌ها شدت را انتخاب می‌کنند. «باز» یا «بسته» فهرست را انتخاب می‌کند.",
  "whatsNew.anomaliesRings": "یک حلقه برای هر مورد نشان می‌دهد تشخیص تا کجا یاد گرفته چه چیزی عادی است.",
  "whatsNew.storageList": "مقصدهای محلی و بیرونی در یک فهرست‌اند. هر مقصد صفحهٔ خودش را دارد.",
  "whatsNew.storageFlow": "3-2-1 به شکل یک تصویر. هر خط از یک حوزه به یک مقصد یک کلید است، محلی هم همین‌طور، و با یک کلیک روشن یا خاموش می‌شود. هر حوزه نشان می‌دهد چند مورد از آن جای دیگری پشتیبان‌گیری می‌کنند.",
  "whatsNew.locationKeep": "نگه‌داری «کوتاه»، «متعادل»، «بلند» یا مقدارهای خودت است. خط زمانی نشان می‌دهد یک قاعده کدام پشتیبان‌ها را نگه می‌دارد.",
  "whatsNew.locationMove": "«جابه‌جایی» نسخهٔ یک حوزه را با کل تاریخچه‌اش به مقصد دیگری می‌برد.",
  "whatsNew.instancesPair": "نمونه‌ها با دوازده کلمه جفت می‌شوند. بعد هر کدام نقش‌هایش را به شکل کاشی نشان می‌دهد.",
  "whatsNew.instancesPhones": "تلفن‌هایی که از راه برنامهٔ Android جفت شده‌اند، کنار نمونه‌ها کارت جداگانه‌ای دارند.",
  "whatsNew.settingsTiles": "تنظیمات چهارده کاشی است. / یا Ctrl+K را بزن تا در همه‌شان بگردی، حتی با نام‌هایی که صفحه‌ها قبلاً داشتند.",
  "whatsNew.settingsPin": "مقصدها و نمونه‌ها کاشی‌های تنظیمات‌اند. این کلید آن‌ها را به نوار کناری سنجاق می‌کند.",
  "whatsNew.settingsWeek": "هفته به شکل یک نوار، با هر اجرای برنامه‌ریزی‌شده از دوشنبه تا یکشنبه.",
  "whatsNew.pairingSteps": "سه کارت نشان می‌دهند جفت‌سازی چطور کار می‌کند. زیر آن‌ها رله چهار شکل دارد و هر کدام تصویر خودش را.",
  "whatsNew.settingsVersion": "«اطلاعات» شامل «نسخه»، «راهنما» و «درباره» است. «نسخه» BombVault، GlimStone، restic و rclone را فهرست می‌کند. دکمهٔ «تازه‌ها» در آن فهرست تغییرها را باز می‌کند، یا وقتی همه را دیده باشی، یادداشت‌های انتشار را.",
